#!/usr/bin/env bash
# Short-form triage pipeline on all five QA dev sets, then the analysis. Usage: bash scripts/run_shortform_dev.sh MODEL
# Do NOT edit this file while it runs (bash reads scripts incrementally).
set -uo pipefail
cd "$(dirname "$0")/.."
for d in popqa nq triviaqa hotpotqa 2wiki; do
  echo "##### $d $(date -u +%FT%TZ)"
  bash scripts/py.sh scripts/run_shortform.py --dataset "$d" --split dev --model "$1" --verifier-device "${VERIFIER_DEVICE:-cpu}" 2>&1 \
    | grep --line-buffered -E '^\{|^wrote|Error|Traceback' | cut -c1-700
  run=$(ls -td results/dev/$d/shortform__*/ | head -n 1)
  bash scripts/py.sh scripts/analyze_shortform.py --run "$run" 2>&1 | tail -n 5
done
echo SHORTFORM_DEV_END
